import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Box, TextField, Button, Typography, Card, CardContent, CircularProgress, Snackbar } from '@mui/material';

const Login = () => {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [loading, setLoading] = useState(false); // Loading state
    const [error, setError] = useState(''); // Error state
    const navigate = useNavigate();

    const handleLogin = async () => {
        try {
            const response = await fetch('http://localhost:3001/api/login', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ username, password }),
            });
    
            if (!response.ok) {
                if (response.status === 401) {
                    console.error('Invalid credentials');
                    setError('Invalid username or password');
                } else {
                    console.error(`Unexpected error: ${response.status}`);
                    setError('An unexpected error occurred');
                }
                return;
            }
    
            const data = await response.json();
            console.log('Login successful:', data);
    
            // Store tokens in localStorage and navigate to the dashboard
            localStorage.setItem('token', data.token);
            localStorage.setItem('sessionToken', data.sessionToken);
            navigate('/dashboard');
        } catch (error) {
            console.error('Error during login:', error.message);
            setError('Failed to connect to the server');
        }
    };
    
    // UseEffect to fetch protected data
    useEffect(() => {
        const fetchProtectedData = async () => {
            const token = localStorage.getItem('token');
            const sessionToken = localStorage.getItem('sessionToken');

            if (!token || !sessionToken) {
                console.error('No tokens found, user is not authenticated.');
                return;
            }

            try {
                const response = await fetch('http://localhost:5000/api/protected', {
                    headers: {
                        Authorization: `Bearer ${token}`,
                        'X-Session-Token': sessionToken,
                    },
                });

                if (response.ok) {
                    const data = await response.json();
                    console.log('Protected data:', data);
                } else {
                    console.error('Failed to fetch protected data');
                }
            } catch (error) {
                console.error('Error fetching protected data:', error);
            }
        };

        // Trigger fetching of protected data after login
        if (localStorage.getItem('token') && localStorage.getItem('sessionToken')) {
            fetchProtectedData();
        }
    }, []); // Empty dependency array ensures this runs only on mount

    return (
        <Box>
            <Card>
                <CardContent>
                    <Typography variant="h5">Login</Typography>
                    <TextField
                        label="Username"
                        value={username}
                        onChange={(e) => setUsername(e.target.value)}
                        fullWidth
                        margin="normal"
                    />
                    <TextField
                        label="Password"
                        type="password"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        fullWidth
                        margin="normal"
                    />
                    <Button onClick={handleLogin} disabled={loading} fullWidth variant="contained" color="primary">
                        {loading ? <CircularProgress size={24} /> : 'Login'}
                    </Button>
                    {error && <Typography color="error">{error}</Typography>}
                </CardContent>
            </Card>

            {/* Snackbar for error messages */}
            {error && (
                <Snackbar
                    open={Boolean(error)}
                    autoHideDuration={6000}
                    onClose={() => setError('')}
                    message={error}
                />
            )}
        </Box>
    );
};

export default Login;
